  async function loadSlots(){try{slots=(await api('/api/slots')).slots;const day=starts=>new Date(new Date(starts).getTime()+2*3600000).toISOString().slice(0,10);const input=$('#meeting-date');input.min=day(new Date().toISOString());if(slots.length&&!input.value)input.value=day(slots[0].starts);renderSlots();}catch(e){$('#meeting-slots').innerHTML=rowsEmpty(e.message);}}
  function renderSlots(){const wanted=$('#meeting-date').value;const available=slots.filter(s=>new Date(new Date(s.starts).getTime()+2*3600000).toISOString().slice(0,10)===wanted);selectedSlot=null;$('#meeting-slots').innerHTML=available.length?available.map(s=>`<button type="button" data-slot="${s.id}" aria-pressed="false">${esc(new Date(s.starts).toLocaleTimeString('en-ZA',{timeZone:'Africa/Johannesburg',hour:'2-digit',minute:'2-digit'}))}</button>`).join(''):rowsEmpty(slots.length?'No available times on this date. Choose another date.':'The studio has not published any available meeting times. Send an enquiry to arrange a conversation.');$$('[data-slot]').forEach(b=>b.addEventListener('click',()=>{selectedSlot=Number(b.dataset.slot);$$('[data-slot]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));}));}
