  // An intentional, nonessential discovery. Never intercept typing in form fields.
  let secret='';document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||e.target.closest('input,textarea,select,[contenteditable]'))return;if(e.key.length===1){secret=(secret+e.key.toLowerCase()).slice(-5);if(secret==='nvtra'&&!$('#easter-dialog').open){$('#easter-dialog').showModal();secret='';}}});$('.nav-brand').addEventListener('dblclick',e=>{e.preventDefault();if(!$('#easter-dialog').open)$('#easter-dialog').showModal();});
